import{_ as a,o as p,c as n,af as i}from"./chunks/framework.B28LkSoM.js";const m=JSON.parse('{"title":"MySQL-进阶篇 · 7. MySQL管理","description":"系统数据库的作用与 mysqladmin、mysqlbinlog、mysqldump、mysqlimport 等常用管理工具","frontmatter":{"title":"MySQL-进阶篇 · 7. MySQL管理","published":"2026-09-18T00:00:00.000Z","tags":["MySQL","数据库"],"description":"系统数据库的作用与 mysqladmin、mysqlbinlog、mysqldump、mysqlimport 等常用管理工具","order":13,"date":"2026-09-18T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/MySQL学习笔记/13-MySQL管理.md","filePath":"posts/学习文档/MySQL学习笔记/13-MySQL管理.md"}'),t={name:"posts/学习文档/MySQL学习笔记/13-MySQL管理.md"};function l(e,s,o,h,d,c){return p(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1789689600000"},[...s[0]||(s[0]=[i(`<h1 id="mysql-进阶篇-·-7-mysql管理" tabindex="-1">MySQL-进阶篇 · 7. MySQL管理 <a class="header-anchor" href="#mysql-进阶篇-·-7-mysql管理" aria-label="Permalink to &quot;MySQL-进阶篇 · 7. MySQL管理&quot;">​</a></h1><h2 id="_7-1-系统数据库" tabindex="-1">7.1 系统数据库 <a class="header-anchor" href="#_7-1-系统数据库" aria-label="Permalink to &quot;7.1 系统数据库&quot;">​</a></h2><p>Mysql数据库安装完成后，自带了一下四个数据库，具体作用如下：</p><table tabindex="0"><thead><tr><th>数据库</th><th>含义</th></tr></thead><tbody><tr><td>mysql</td><td>存储MySQL服务器正常运行所需要的各种信息 （时区、主从、用户、权限等）</td></tr><tr><td>information_schema</td><td>提供了访问数据库元数据的各种表和视图，包含数据库、表、字段类型及访问权限等</td></tr><tr><td>performance_schema</td><td>为MySQL服务器运行时状态提供了一个底层监控功能，主要用于收集数据库服务器性能参数</td></tr><tr><td>sys</td><td>包含了一系列方便 DBA 和开发人员利用 performance_schema性能数据库进行性能调优和诊断的视图</td></tr></tbody></table><h2 id="_7-2-常用工具" tabindex="-1">7.2 常用工具 <a class="header-anchor" href="#_7-2-常用工具" aria-label="Permalink to &quot;7.2 常用工具&quot;">​</a></h2><h3 id="_7-2-1-mysql" tabindex="-1">7.2.1 mysql <a class="header-anchor" href="#_7-2-1-mysql" aria-label="Permalink to &quot;7.2.1 mysql&quot;">​</a></h3><p>该mysql不是指mysql服务，而是指mysql的客户端工具。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法 ：</span></span>
<span class="line"><span>    mysql   [options]   [database]</span></span>
<span class="line"><span>选项 ：</span></span>
<span class="line"><span>    -u, --user=name         #指定用户名</span></span>
<span class="line"><span>    -p, --password[=name]           #指定密码</span></span>
<span class="line"><span>    -h, --host=name         #指定服务器IP或域名</span></span>
<span class="line"><span>    -P, --port=port             #指定连接端口</span></span>
<span class="line"><span>    -e, --execute=name          #执行SQL语句并退出</span></span></code></pre></div><p>-e选项可以在Mysql客户端执行SQL语句，而不用连接到MySQL数据库再执行，对于一些批处理脚本，这种方式尤其方便。</p><p>示例：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysql </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uroot –p123456 db01 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;select * from stu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><img src="https://img.tsh520.cn/file/blog/article/p136_1.webp" alt=""></p><h3 id="_7-2-2-mysqladmin" tabindex="-1">7.2.2 mysqladmin <a class="header-anchor" href="#_7-2-2-mysqladmin" aria-label="Permalink to &quot;7.2.2 mysqladmin&quot;">​</a></h3><p>mysqladmin 是一个执行管理操作的客户端程序。可以用它来检查服务器的配置和当前状态、创建并删除数据库等。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>通过帮助文档查看选项：</span></span>
<span class="line"><span>    mysqladmin --help</span></span></code></pre></div><p><img src="https://img.tsh520.cn/file/blog/article/p136_2.webp" alt=""></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:</span></span>
<span class="line"><span>    mysqladmin [options] command ...</span></span>
<span class="line"><span>选项:</span></span>
<span class="line"><span>    -u, --user=name             #指定用户名</span></span>
<span class="line"><span>    -p, --password[=name]       #指定密码</span></span>
<span class="line"><span>    -h, --host=name             #指定服务器IP或域名</span></span>
<span class="line"><span>    -P, --port=port             #指定连接端口</span></span></code></pre></div><p>示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysqladmin -uroot –p1234 drop &#39;test01&#39;;</span></span>
<span class="line"><span>mysqladmin -uroot –p1234 version;</span></span></code></pre></div><p><img src="https://img.tsh520.cn/file/blog/article/p137_1.webp" alt=""></p><h3 id="_7-2-3-mysqlbinlog" tabindex="-1">7.2.3 mysqlbinlog <a class="header-anchor" href="#_7-2-3-mysqlbinlog" aria-label="Permalink to &quot;7.2.3 mysqlbinlog&quot;">​</a></h3><p>由于服务器生成的二进制日志文件以二进制格式保存，所以如果想要检查这些文本的文本格式，就会使用到mysqlbinlog 日志管理工具。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法 ：</span></span>
<span class="line"><span>    mysqlbinlog [options]  log-files1 log-files2 ...</span></span>
<span class="line"><span>选项 ：</span></span>
<span class="line"><span>    -d, --database=name         指定数据库名称，只列出指定的数据库相关操作。</span></span>
<span class="line"><span>    -o, --offset=#              忽略掉日志中的前n行命令。</span></span>
<span class="line"><span>    -r,--result-file=name       将输出的文本格式日志输出到指定文件。</span></span>
<span class="line"><span>    -s, --short-form            显示简单格式， 省略掉一些信息。</span></span>
<span class="line"><span>    --start-datatime=date1  --stop-datetime=date2       指定日期间隔内的所有日志。--start-position=pos1 --stop-position=pos2          指定位置间隔内的所有日志。</span></span></code></pre></div><p>示例:</p><p>A. 查看 binlog.000008这个二进制文件中的数据信息</p><p><img src="https://img.tsh520.cn/file/blog/article/p137_2.webp" alt=""></p><p>上述查看到的二进制日志文件数据信息量太多了，不方便查询。 我们可以加上一个参数 -s 来显示简单格式。</p><p><img src="https://img.tsh520.cn/file/blog/article/p138_1.webp" alt=""></p><h3 id="_7-2-4-mysqlshow" tabindex="-1">7.2.4 mysqlshow <a class="header-anchor" href="#_7-2-4-mysqlshow" aria-label="Permalink to &quot;7.2.4 mysqlshow&quot;">​</a></h3><p>mysqlshow 客户端对象查找工具，用来很快地查找存在哪些数据库、数据库中的表、表中的列或者索引。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法 ：</span></span>
<span class="line"><span>    mysqlshow [options] [db_name [table_name [col_name]]]</span></span>
<span class="line"><span>选项 ：</span></span>
<span class="line"><span>    --count     显示数据库及表的统计信息（数据库，表 均可以不指定）</span></span>
<span class="line"><span>    -i      显示指定数据库或者指定表的状态信息</span></span>
<span class="line"><span>示例：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    #查询test库中每个表中的字段书，及行数</span></span>
<span class="line"><span>    mysqlshow -uroot -p2143 test --count</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    #查询test库中book表的详细情况</span></span>
<span class="line"><span>    mysqlshow -uroot -p2143 test book --count</span></span></code></pre></div><p>示例：</p><p>A. 查询每个数据库的表的数量及表中记录的数量mysqlshow -uroot -p1234 --count</p><p><img src="https://img.tsh520.cn/file/blog/article/p139_1.webp" alt=""></p><p>B. 查看数据库db01的统计信息</p><p>mysqlshow -uroot -p1234 db01 --count</p><p><img src="https://img.tsh520.cn/file/blog/article/p139_2.webp" alt=""></p><p>C. 查看数据库db01中的course表的信息</p><p>mysqlshow -uroot -p1234 db01 course --count</p><p><img src="https://img.tsh520.cn/file/blog/article/p139_3.webp" alt=""></p><p>D. 查看数据库db01中的course表的id字段的信息</p><p>mysqlshow -uroot -p1234 db01 course id --count</p><p><img src="https://img.tsh520.cn/file/blog/article/p139_4.webp" alt=""></p><h3 id="_7-2-5-mysqldump" tabindex="-1">7.2.5 mysqldump <a class="header-anchor" href="#_7-2-5-mysqldump" aria-label="Permalink to &quot;7.2.5 mysqldump&quot;">​</a></h3><p>mysqldump 客户端工具用来备份数据库或在不同数据库之间进行数据迁移。备份内容包含创建表，及插入表的SQL语句。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">语法 ：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    mysqldump [options] db_name [tables]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    mysqldump [options] </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--database/-B db1 [db2 db3...]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    mysqldump [options] </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--all-databases/-A</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">连接选项 ：</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--user=name                 指定用户名</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--password[=name]           指定密码</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--host=name                 指定服务器ip或域名</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">P, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--port=#                    指定连接端口</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">输出选项：</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    --add-drop-database         在每个数据库创建语句前加上 drop database 语句</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    --add-drop-table            在每个表创建语句前加上 drop table 语句 , 默认开启 ; 不开启 (--skip-add-drop-table)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--no-create-db          不包含数据库的创建语句</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--no-create-info        不包含数据表的创建语句</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--no-data                不包含数据</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">     -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">T, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--tab=name             自动生成两个文件：一个.sql文件，创建表结构的语句；一个.txt文件，数据文件</span></span></code></pre></div><p>示例:</p><p>A. 备份db01数据库</p><p>mysqldump -uroot -p1234 db01 &gt; db01.sql</p><p><img src="https://img.tsh520.cn/file/blog/article/p140_1.webp" alt=""></p><p>可以直接打开db01.sql，来查看备份出来的数据到底什么样。</p><p><img src="https://img.tsh520.cn/file/blog/article/p141_1.webp" alt=""></p><p>备份出来的数据包含：</p><ul><li>删除表的语句创建表的语句数据插入语句</li></ul><p>如果我们在数据备份时，不需要创建表，或者不需要备份数据，只需要备份表结构，都可以通过对应的参数来实现。</p><p>B. 备份db01数据库中的表数据，不备份表结构(-t)</p><p>mysqldump -uroot -p1234 -t db01 &gt; db01.sql</p><p><img src="https://img.tsh520.cn/file/blog/article/p141_2.webp" alt=""></p><p>打开 db02.sql ，来查看备份的数据，只有insert语句，没有备份表结构。</p><p><img src="https://img.tsh520.cn/file/blog/article/p141_3.webp" alt=""></p><p>C. 将db01数据库的表的表结构与数据分开备份(-T)</p><p>mysqldump -uroot -p1234 -T /root db01 score</p><p><img src="https://img.tsh520.cn/file/blog/article/p142_1.webp" alt=""></p><p>执行上述指令，会出错，数据不能完成备份，原因是因为我们所指定的数据存放目录/root，MySQL认为是不安全的，需要存储在MySQL信任的目录下。那么，哪个目录才是MySQL信任的目录呢，可以查看一下系统变量 secure_file_priv 。执行结果如下：</p><p><img src="https://img.tsh520.cn/file/blog/article/p142_2.webp" alt=""></p><p><img src="https://img.tsh520.cn/file/blog/article/p142_3.webp" alt=""></p><p>上述的两个文件 score.sql 中记录的就是表结构文件，而 score.txt 就是表数据文件，但是需要注意表数据文件，并不是记录一条条的insert语句，而是按照一定的格式记录表结构中的数据。如下：</p><p><img src="https://img.tsh520.cn/file/blog/article/p142_4.webp" alt=""></p><h3 id="_7-2-6-mysqlimport-source" tabindex="-1">7.2.6 mysqlimport/source <a class="header-anchor" href="#_7-2-6-mysqlimport-source" aria-label="Permalink to &quot;7.2.6 mysqlimport/source&quot;">​</a></h3><p>1). mysqlimport</p><p>mysqlimport 是客户端数据导入工具，用来导入mysqldump 加 -T 参数后导出的文本文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法 ：</span></span>
<span class="line"><span>    mysqlimport [options]  db_name  textfile1  [textfile2...]</span></span>
<span class="line"><span>示例 ：</span></span>
<span class="line"><span>    mysqlimport -uroot -p2143 test /tmp/city.txt</span></span></code></pre></div><p><img src="https://img.tsh520.cn/file/blog/article/p142_5.webp" alt=""></p><p>2). source</p><p>如果需要导入sql文件,可以使用mysql中的source 指令 :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法 ：</span></span>
<span class="line"><span>    source /root/xxxxx.sql</span></span></code></pre></div>`,76)])])}const g=a(t,[["render",l]]);export{m as __pageData,g as default};
